CREATE TYPE "WorkspaceRole" AS ENUM ('OWNER','ADMIN','OPERATOR','VIEWER');
CREATE TYPE "AgentStatus" AS ENUM ('ACTIVE','PAUSED','DISABLED','ARCHIVED');
CREATE TYPE "VersionStatus" AS ENUM ('DRAFT','PRODUCTION','ARCHIVED');
CREATE TYPE "VersionSource" AS ENUM ('AI_DISCOVERY','AI_RECOVERY','USER_EDIT');
CREATE TYPE "ApprovalStatus" AS ENUM ('PENDING','APPROVED','REJECTED','EXPIRED');
CREATE TABLE "users" ("id" TEXT PRIMARY KEY,"identity_provider_uid" TEXT NOT NULL UNIQUE,"email" TEXT NOT NULL UNIQUE,"display_name" TEXT,"avatar_url" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "workspaces" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "workspace_members" ("id" TEXT PRIMARY KEY,"workspace_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"role" "WorkspaceRole" NOT NULL DEFAULT 'OPERATOR',CONSTRAINT "workspace_members_workspace_id_fkey" FOREIGN KEY("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE,CONSTRAINT "workspace_members_user_id_fkey" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE,UNIQUE("workspace_id","user_id"));
CREATE TABLE "agents" ("id" TEXT PRIMARY KEY,"workspace_id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"goal" TEXT NOT NULL,"target_url" TEXT NOT NULL,"allowed_domains" JSONB NOT NULL,"status" "AgentStatus" NOT NULL DEFAULT 'ACTIVE',"active_version_id" TEXT,"connection_id" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"row_version" INTEGER NOT NULL DEFAULT 1,CONSTRAINT "agents_workspace_id_fkey" FOREIGN KEY("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE);
CREATE INDEX "agents_workspace_id_created_at_idx" ON "agents"("workspace_id","created_at");
CREATE TABLE "agent_versions" ("id" TEXT PRIMARY KEY,"agent_id" TEXT NOT NULL,"label" TEXT NOT NULL,"status" "VersionStatus" NOT NULL DEFAULT 'DRAFT',"source" "VersionSource" NOT NULL,"parent_version_id" TEXT,"workflow_spec" JSONB NOT NULL,"extraction_schema" JSONB NOT NULL,"compiled_artifact_path" TEXT,"verification" JSONB,"risk_level" TEXT NOT NULL DEFAULT 'LOW',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"promoted_at" TIMESTAMP(3),CONSTRAINT "agent_versions_agent_id_fkey" FOREIGN KEY("agent_id") REFERENCES "agents"("id") ON DELETE CASCADE,UNIQUE("agent_id","label"));
CREATE TABLE "runs" ("id" TEXT PRIMARY KEY,"workspace_id" TEXT NOT NULL,"agent_id" TEXT NOT NULL,"version_id" TEXT,"trigger_type" TEXT NOT NULL,"status" TEXT NOT NULL,"execution_mode" TEXT NOT NULL,"current_step" TEXT,"idempotency_key" TEXT NOT NULL UNIQUE,"retry_count" INTEGER NOT NULL DEFAULT 0,"recovery_count" INTEGER NOT NULL DEFAULT 0,"model_call_count" INTEGER NOT NULL DEFAULT 0,"input_tokens" INTEGER NOT NULL DEFAULT 0,"output_tokens" INTEGER NOT NULL DEFAULT 0,"result" JSONB,"error_code" TEXT,"error_message" TEXT,"lease_owner" TEXT,"lease_expires_at" TIMESTAMP(3),"started_at" TIMESTAMP(3),"completed_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "runs_workspace_id_fkey" FOREIGN KEY("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE,CONSTRAINT "runs_agent_id_fkey" FOREIGN KEY("agent_id") REFERENCES "agents"("id") ON DELETE CASCADE,CONSTRAINT "runs_version_id_fkey" FOREIGN KEY("version_id") REFERENCES "agent_versions"("id") ON DELETE SET NULL);
CREATE INDEX "runs_workspace_id_created_at_idx" ON "runs"("workspace_id","created_at");CREATE INDEX "runs_agent_id_created_at_idx" ON "runs"("agent_id","created_at");CREATE INDEX "runs_status_idx" ON "runs"("status");
CREATE TABLE "run_steps" ("id" TEXT PRIMARY KEY,"run_id" TEXT NOT NULL,"workflow_step_id" TEXT NOT NULL,"sequence_number" INTEGER NOT NULL,"action_type" TEXT NOT NULL,"status" TEXT NOT NULL,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "run_steps_run_id_fkey" FOREIGN KEY("run_id") REFERENCES "runs"("id") ON DELETE CASCADE,UNIQUE("run_id","workflow_step_id","sequence_number"));
CREATE TABLE "run_events" ("id" TEXT PRIMARY KEY,"run_id" TEXT NOT NULL,"event_type" TEXT NOT NULL,"source" TEXT NOT NULL,"message" TEXT NOT NULL,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "run_events_run_id_fkey" FOREIGN KEY("run_id") REFERENCES "runs"("id") ON DELETE CASCADE);CREATE INDEX "run_events_run_id_created_at_idx" ON "run_events"("run_id","created_at");
CREATE TABLE "model_invocations" ("id" TEXT PRIMARY KEY,"run_id" TEXT NOT NULL,"agent_type" TEXT NOT NULL,"model" TEXT NOT NULL,"input_tokens" INTEGER NOT NULL DEFAULT 0,"output_tokens" INTEGER NOT NULL DEFAULT 0,"latency_ms" INTEGER NOT NULL DEFAULT 0,"success" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "model_invocations_run_id_fkey" FOREIGN KEY("run_id") REFERENCES "runs"("id") ON DELETE CASCADE);
CREATE TABLE "recovery_attempts" ("id" TEXT PRIMARY KEY,"run_id" TEXT NOT NULL,"attempt_number" INTEGER NOT NULL,"failed_step_id" TEXT NOT NULL,"diagnosis" JSONB NOT NULL,"patch" JSONB NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"risk_level" TEXT NOT NULL,"verification" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "recovery_attempts_run_id_fkey" FOREIGN KEY("run_id") REFERENCES "runs"("id") ON DELETE CASCADE);
CREATE TABLE "approvals" ("id" TEXT PRIMARY KEY,"workspace_id" TEXT NOT NULL,"run_id" TEXT,"type" TEXT NOT NULL,"status" "ApprovalStatus" NOT NULL DEFAULT 'PENDING',"risk_level" TEXT NOT NULL DEFAULT 'LOW',"reason" TEXT NOT NULL,"payload" JSONB,"resolved_by" TEXT,"requested_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resolved_at" TIMESTAMP(3),CONSTRAINT "approvals_workspace_id_fkey" FOREIGN KEY("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE,CONSTRAINT "approvals_run_id_fkey" FOREIGN KEY("run_id") REFERENCES "runs"("id") ON DELETE CASCADE);CREATE INDEX "approvals_workspace_id_status_idx" ON "approvals"("workspace_id","status");
CREATE TABLE "schedules" ("id" TEXT PRIMARY KEY,"workspace_id" TEXT NOT NULL,"agent_id" TEXT NOT NULL,"name" TEXT NOT NULL,"cron_expression" TEXT NOT NULL,"timezone" TEXT NOT NULL DEFAULT 'UTC',"enabled" BOOLEAN NOT NULL DEFAULT true,"scheduler_job_name" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "schedules_workspace_id_fkey" FOREIGN KEY("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE,CONSTRAINT "schedules_agent_id_fkey" FOREIGN KEY("agent_id") REFERENCES "agents"("id") ON DELETE CASCADE);
CREATE TABLE "integrations" ("id" TEXT PRIMARY KEY,"workspace_id" TEXT NOT NULL,"provider" TEXT NOT NULL,"status" TEXT NOT NULL,"display_name" TEXT NOT NULL,"metadata" JSONB,"secret_manager_ref" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "integrations_workspace_id_fkey" FOREIGN KEY("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE);
CREATE TABLE "connections" ("id" TEXT PRIMARY KEY,"workspace_id" TEXT NOT NULL,"name" TEXT NOT NULL,"allowed_domains" JSONB NOT NULL,"secret_manager_ref" TEXT NOT NULL,"credential_fields" JSONB NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "connections_workspace_id_fkey" FOREIGN KEY("workspace_id") REFERENCES "workspaces"("id") ON DELETE CASCADE);
CREATE TABLE "audit_logs" ("id" TEXT PRIMARY KEY,"workspace_id" TEXT NOT NULL,"actor_id" TEXT,"action" TEXT NOT NULL,"resource_type" TEXT NOT NULL,"resource_id" TEXT,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX "audit_logs_workspace_id_created_at_idx" ON "audit_logs"("workspace_id","created_at");
CREATE TABLE "workspace_settings" ("workspace_id" TEXT PRIMARY KEY,"default_model" TEXT NOT NULL DEFAULT 'gemini-3.7-flash',"max_run_duration" INTEGER NOT NULL DEFAULT 600,"max_recovery_attempts" INTEGER NOT NULL DEFAULT 3,"retention_days" INTEGER NOT NULL DEFAULT 30,"auto_promote_low_risk" BOOLEAN NOT NULL DEFAULT true,"updated_at" TIMESTAMP(3) NOT NULL);
